fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            // Use the lines or split_inclusive method depending on keepends
            if keepends {
                // split_inclusive keeps the line-ending characters
                let lines: Vec<String> = s
                    .split_inclusive(|c| c == '\n' || c == '\r')
                    // Handle CRLF ("\r\n") case properly:
                    // combine \r and \n if they appear consecutively as a single line ending
                    .fold(Vec::new(), |mut acc, part| {
                        if !acc.is_empty() {
                            let last = acc.last_mut().unwrap();
                            if last.ends_with('\r') && part == "\n" {
                                last.push_str("\n");
                            } else {
                                acc.push(part.to_string());
                            }
                        } else {
                            acc.push(part.to_string());
                        }
                        acc
                    });
                // Because split_inclusive may split on each char, make sure to handle empty input carefully.
                if lines.is_empty() {
                    vec![String::new()]
                } else {
                    lines
                }
            } else {
                // split at line boundaries, dropping the line-ending chars
                let lines: Vec<String> = s.lines().map(|line| line.to_string()).collect();
                if lines.is_empty() {
                    vec![String::new()]
                } else {
                    lines
                }
            }
        })
        .collect()
}